private val N=Color(0xFF02050D);private val P=Color(0xDD091525);private val C=Color(0xFF5EE5FF);private val V=Color(0xFF8E7DFF);private val M=Color(0xFF9EB0C7)
private enum class Tab{CHAT,VOICE,MEMORY,TOOLS}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun FinalScreen(vm:GemmaViewModel,onOpenSettings:()->Unit,onRequestSpeech:()->Unit){val s by vm.chat.collectAsStateWithLifecycle();val d by vm.draft.collectAsStateWithLifecycle();val voice by vm.voiceEnabled.collectAsStateWithLifecycle();val live by vm.liveMode.collectAsStateWithLifecycle();var tab by rememberSaveable{mutableStateOf(Tab.CHAT)};val drawer=rememberDrawerState(DrawerValue.Closed);val scope=rememberCoroutineScope()
ModalNavigationDrawer(drawerState=drawer,drawerContent={ModalDrawerSheet(drawerContainerColor=Color(0xFF07101C)){Spacer(Modifier.height(42.dp));Text("GEMMA",Modifier.padding(20.dp),color=C,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);HorizontalDivider(color=Color(0xFF203047));Text("Conversations",Modifier.padding(20.dp),color=Color.White,fontWeight=FontWeight.Bold);Text("Gemma's primary conversation",Modifier.padding(20.dp),color=M);Text("More conversation management will appear automatically when Vision exposes it through the API.",Modifier.padding(20.dp),color=M,style=MaterialTheme.typography.bodySmall)}}){Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(N,Color(0xFF08172A),N)))){Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().statusBarsPadding().padding(8.dp),verticalAlignment=Alignment.CenterVertically){TextButton(onClick={scope.launch{drawer.open()}}){Text("☰",color=C,style=MaterialTheme.typography.titleLarge)};Column(Modifier.weight(1f)){Text("Gemma",color=Color.White,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text(s.statusLine,color=if(s.conversationId!=null)Color(0xFF63E6A6)else M,style=MaterialTheme.typography.labelMedium)};IconButton(onClick=onOpenSettings){Icon(Icons.Default.Settings,"Settings",tint=M)}};Box(Modifier.weight(1f)){when(tab){Tab.CHAT->Chat(s,vm);Tab.VOICE->Voice(s,voice,live,vm,onRequestSpeech);Tab.MEMORY->Info("Memory","Gemma's shared memory stays on Vision. The phone will never fork a second private memory database.");Tab.TOOLS->Tools(vm)}};if(tab==Tab.CHAT)Composer(s,d,vm,onRequestSpeech);Row(Modifier.fillMaxWidth().navigationBarsPadding().background(Color(0xF7050912)),horizontalArrangement=Arrangement.SpaceEvenly){Tab.entries.forEach{t->TextButton(onClick={tab=t}){Column(horizontalAlignment=Alignment.CenterHorizontally){Text(when(t){Tab.CHAT->"●";Tab.VOICE->"◉";Tab.MEMORY->"◇";Tab.TOOLS->"⌘"},color=if(tab==t)C else M);Text(t.name.lowercase().replaceFirstChar{it.uppercase()},color=if(tab==t)C else M,style=MaterialTheme.typography.labelSmall)}}}}}}}}

@Composable private fun Portrait(s:ChatState,big:Boolean=true){Box(Modifier.size(if(big)260.dp else 150.dp,if(big)330.dp else 190.dp).clip(RoundedCornerShape(if(big)34.dp else 28.dp)).background(Color(0xFF10263A))){Image(painterResource(R.drawable.gemma_portrait),"Gemma",Modifier.fillMaxSize(),contentScale=ContentScale.Crop);Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color.Transparent,Color(0x22000000),Color(0xCC020711)))));Surface(Modifier.align(Alignment.BottomCenter).padding(12.dp),shape=RoundedCornerShape(18.dp),color=Color(0xC907111D),border=BorderStroke(1.dp,if(s.busy)V else C)){Text(if(s.busy)s.activity.ifBlank{"Just thinking…"}else"Online",Modifier.padding(horizontal=14.dp,vertical=7.dp),color=Color.White,style=MaterialTheme.typography.labelMedium)}}}
@Composable private fun Chat(s:ChatState,vm:GemmaViewModel){if(s.messages.isEmpty())Column(Modifier.fillMaxSize(),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Portrait(s,false);Spacer(Modifier.height(16.dp));Text("Gemma",color=Color.White,style=MaterialTheme.typography.headlineMedium);Text("Your Gemma on Vision",color=M)}else LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(14.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){if(s.hasOlder)item{TextButton(onClick=vm::loadOlder){Text("Earlier messages")}};items(s.messages,key={it.key}){Bubble(it)}}}
@Composable private fun Bubble(m:ChatMessage){val mine=m.role=="user";val ctx=LocalContext.current;Column(Modifier.fillMaxWidth(),horizontalAlignment=if(mine)Alignment.End else Alignment.Start){Text(if(mine)"You"else"Gemma",color=if(mine)M else C,style=MaterialTheme.typography.labelSmall);Surface(shape=RoundedCornerShape(20.dp),color=if(mine)Color(0xDD20375E)else P,border=BorderStroke(1.dp,if(mine)Color(0x554C7BD9)else Color(0x445EE5FF)),modifier=Modifier.widthIn(max=560.dp)){Text(if(m.streaming&&m.text.isBlank())"…"else m.text,Modifier.padding(15.dp),color=Color.White)};Row{TextButton(onClick={(ctx.getSystemService(Context.CLIPBOARD_SERVICE)as ClipboardManager).setPrimaryClip(ClipData.newPlainText("Gemma",m.text))}){Text("Copy",color=M,style=MaterialTheme.typography.labelSmall)};if(!mine)TextButton(onClick={}){Text("Play",color=Color(0xFF61748C),style=MaterialTheme.typography.labelSmall)}};m.problem?.let{Text(it,color=MaterialTheme.colorScheme.error,style=MaterialTheme.typography.labelSmall)}}}
@Composable private fun Composer(s:ChatState,d:String,vm:GemmaViewModel,mic:()->Unit){Row(Modifier.fillMaxWidth().imePadding().background(Color(0xEE050A12)).padding(10.dp),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=mic,enabled=!s.busy){Text("🎙",style=MaterialTheme.typography.titleLarge)};OutlinedTextField(d,vm::onDraftChange,Modifier.weight(1f),placeholder={Text("Message Gemma…")},shape=RoundedCornerShape(24.dp),maxLines=5);Spacer(Modifier.width(8.dp));if(s.busy)Button(onClick=vm::stop,shape=CircleShape,contentPadding=PaddingValues(14.dp)){Text("■")}else Button(onClick=vm::send,enabled=d.isNotBlank()&&s.conversationId!=null,shape=CircleShape,contentPadding=PaddingValues(14.dp)){Text("➤")}}}
@Composable private fun Voice(s:ChatState,voice:Boolean,live:Boolean,vm:GemmaViewModel,mic:()->Unit){Column(Modifier.fillMaxSize().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Portrait(s);Spacer(Modifier.height(16.dp));Text(if(live)"LIVE WITH GEMMA"else"VOICE",color=C,fontWeight=FontWeight.Bold);Text(if(s.busy)s.activity.ifBlank{"Gemma is answering…"}else if(live)"Listening automatically"else if(s.voiceReady)"Tiffany voice ready"else"Vision voice unavailable",color=M);Spacer(Modifier.height(20.dp));Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Button(onClick={vm.setVoiceEnabled(!voice)}){Text(if(voice)"🔊 Speaker"else"🔇 Muted")};Button(onClick=mic,enabled=!s.busy){Text("🎙 Talk")}};Spacer(Modifier.height(10.dp));Button(onClick={vm.setLiveMode(!live)},colors=ButtonDefaults.buttonColors(containerColor=if(live)Color(0xFF7A315F)else Color(0xFF145F82))){Text(if(live)"End Live Mode"else"Start Live Mode")};if(s.busy){Spacer(Modifier.height(10.dp));OutlinedButton(onClick=vm::stop){Text("Stop / interrupt")}};Spacer(Modifier.height(12.dp));Text("Live mode: you speak → Android transcribes → Vision answers → Tiffany voice plays → the microphone opens again.",color=M,style=MaterialTheme.typography.bodySmall)}}
@Composable private fun Info(t:String,b:String){Column(Modifier.fillMaxSize().padding(28.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text(t,color=Color.White,style=MaterialTheme.typography.headlineMedium);Spacer(Modifier.height(12.dp));Text(b,color=M)}}
@Composable private fun Tools(vm:GemmaViewModel){Column(Modifier.fillMaxSize().padding(22.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text("Tools",color=Color.White,style=MaterialTheme.typography.headlineMedium);Card("Research","Use Gemma's existing Vision research tools."){vm.onDraftChange("Research: ")};Card("Code Help","Start a coding task."){vm.onDraftChange("Help me with this code: ")};Card("Image analysis","Vision already supports images; Android attachment upload still needs the server upload contract.",{});Card("Transcribe","Waiting for a Vision transcription endpoint.",{});Card("File search","Waiting for a security-scoped, read-only Vision file API.",{})}}
@Composable private fun Card(t:String,b:String,f:()->Unit){Surface(onClick=f,shape=RoundedCornerShape(18.dp),color=P,border=BorderStroke(1.dp,Color(0x333AC7EF))){Column(Modifier.fillMaxWidth().padding(16.dp)){Text(t,color=C,fontWeight=FontWeight.Bold);Text(b,color=M,style=MaterialTheme.typography.bodySmall)}}}
